{
  "steps": [
    {
      "id": 1,
      "claim": "Sexual reproduction involves the fusion of haploid gametes from two parents to form a diploid zygote.",
      "evidence": "Biology definition of sexual reproduction (e.g., Campbell Biology, 12th ed., p. 124).",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Meiosis creates new allele combinations through crossing‑over and independent assortment of homologous chromosomes.",
      "evidence": "Genetics textbooks: meiosis produces 2ⁿ⁺¹ possible gamete genotypes (where n = number of chromosome pairs).",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Fertilization mixes the distinct gametes, so each offspring inherits a unique combination of alleles from both parents.",
      "evidence": "Fertilization restores diploidy and combines two genetically diverse haploid genomes.",
      "weight": 0.15,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Asexual reproduction produces offspring from a single parent by mitotic division, yielding clones that differ only by rare mutations.",
      "evidence": "Definition of asexual reproduction (binary fission, budding, etc.) produces genetically identical copies.",
      "weight": 0.10,
      "depends_on": []
    },
    {
      "id": 5,
      "claim": "The rate of new genetic variation from mutation (~10⁻⁸ per base per generation) is far lower than the variation generated each generation by meiotic recombination.",
      "evidence": "Empirical mutation‑rate estimates (e.g., Keightley & Eyre‑Walker, 2007) versus combinatorial possibilities of meiosis.",
      "weight": 0.15,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Greater genetic variation among offspring enhances a population’s capacity to adapt to environmental changes and resist diseases.",
      "evidence": "Fundamental principle of natural selection: diverse phenotypes increase the chance that some individuals survive novel stresses.",
      "weight": 0.20,
      "depends_on": [3, 5]
    },
    {
      "id": 7,
      "claim": "Option (A) – “There is greater variation among the offspring” – directly states this primary advantage of sexual reproduction.",
      "evidence": "Mapping of the conclusion in step 6 to the answer choice.",
      "weight": 0.05,
      "depends_on": [6]
    },
    {
      "id": 8,
      "claim": "Options (B), (C), and (D) describe characteristics of asexual reproduction or are not advantages of sexual reproduction, so they are incorrect.",
      "evidence": "B describes cloning; C describes single‑parent reproduction; D denies the need for gametes, which sexual reproduction requires.",
      "weight": 0.05,
      "depends_on": [1, 4]
    }
  ],
  "answer": "A",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "B",
      "reason_rejected": "Identical offspring are a feature of asexual reproduction, not an advantage of sexual reproduction."
    },
    {
      "answer": "C",
      "reason_rejected": "Needing only one parent is an advantage of asexual reproduction; sexual reproduction requires two parents."
    },
    {
      "answer": "D",
      "reason_rejected": "Sexual reproduction explicitly requires sex cells (gametes); lacking them is a trait of asexual reproduction."
    }
  ]
}
